from taf.gnb.oam.coam.cu.schemas.base import SchemaField, SchemaObject


class Alarms(SchemaObject):
    uuid = SchemaField(name="uuid")
    severity = SchemaField(name="severity")
    alarm_id = SchemaField(name="alarm_id")
    alarm_name = SchemaField(name="alarm_name")
    fault_id = SchemaField(name="fault_id")
    fault_name = SchemaField(name="fault_name")

    def __init__(self, uuid, severity, alarm_id, alarm_name, fault_id, fault_name):
        self.uuid = uuid
        self.severity = severity
        self.alarm_id = alarm_id
        self.alarm_name = alarm_name
        self.fault_id = fault_id
        self.fault_name = fault_name

        super(Alarms, self).__init__()


class IpInterface(SchemaObject):
    interface_name = SchemaField(name='interface_name')
    ip_address = SchemaField(name='ip_address')

    def __init__(self, interface_name, ip_address):
        self.interface_name = interface_name
        self.ip_address = ip_address

        super(IpInterface, self).__init__()


class DistNames(SchemaObject):
    config = SchemaField(name='config')
    runtime = SchemaField(name='runtime')

    def __init__(self, config, runtime):
        self.config = config
        self.runtime = runtime

        super(DistNames, self).__init__()


class VMSInfov1(SchemaObject):
    id = SchemaField(name="id")
    name = SchemaField(name="name")
    hostname = SchemaField(name="hostname")
    role = SchemaField(name='role', optional=True)
    availability_status = SchemaField(name="availability_status")
    operational_state = SchemaField(name="operational_state")
    software_version = SchemaField(name="software_version", not_null=True)
    alarms = SchemaField(name="alarms", klass=Alarms, many=True)
    ip_interfaces = SchemaField(name="ip_interfaces", klass=IpInterface, many=True)
    dist_names = SchemaField(name='dist_names', klass=DistNames, optional=True)
    cores = SchemaField(name="cores", optional=True)
    cpu_load = SchemaField(name="cpu_load", optional=True)
    memory_total = SchemaField(name="memory_total", optional=True)
    memory_used = SchemaField(name="memory_used", optional=True)

    def __init__(self, id, name, hostname, role, availability_status, operational_state, software_version, alarms,
                 ip_interfaces, dist_names, cores, cpu_load, memory_total, memory_used):
        self.id = id
        self.name = name
        self.hostname = hostname
        self.role = role
        self.availability_status = availability_status
        self.operational_state = operational_state
        self.software_version = software_version
        self.alarms = alarms
        self.ip_interfaces = ip_interfaces
        self.dist_names = dist_names
        self.cores = cores
        self.cpu_load = cpu_load
        self.memory_total = memory_total
        self.memory_used = memory_used

        super(VMSInfov1, self).__init__()
